import { useReducer } from "react";
import Header from "./components/Header";
import Main from "./components/Main";
import StartQuiz from "./components/StartQuiz";

function App() {
  const [state, dispatch] = useReducer(
    (state, action) => {
      switch (action.type) {
        case "START_QUIZ":
          return { ...state, quizStarted: true };
        default:
          return state;
      }
    },
    { quizStarted: false },
  );

  return (
    <div className="app">
      <Header />
      <Main>
        <StartQuiz />
      </Main>
    </div>
  );
}

export default App;
